import styled from 'styled-components';
import MarkdownView from 'react-showdown';

// CMS uploads sit next to the entry's index.md and are referenced by bare file
// name; gatsby-node copies them to the page's URL, so prefix the page slug.
export const mediaSrc = (src, base) => (base && /^[^/:]+$/.test(src) ? base + src : src);

// Renders the CMS rich-text fields (Summary, Context, Solution). Tables come
// from the CMS "Table" block; images, GIFs and Google Forms are lazy-loaded so
// a long page only downloads what the reader scrolls to.
const pageMedia = (base) => ({
  type: 'output',
  filter: (html) =>
    html
      .replace(/(<img[^>]*?\ssrc=")([^"]*)/g, (_, tag, src) => tag + mediaSrc(src, base))
      .replace(/<img(?![^>]*\bloading=)/g, '<img loading="lazy" decoding="async"')
      .replace(/<iframe(?![^>]*\bloading=)/g, '<iframe loading="lazy"')
});

const Markdown = styled(MarkdownView).attrs(({ base }) => ({ base: undefined, options: { tables: true }, extensions: [pageMedia(base)] }))`
  img {
    max-width: 100%;
    height: auto;
  }

  table {
    display: block;
    overflow-x: auto;
    border-collapse: collapse;
    margin: 16px 0;
  }

  th,
  td {
    padding: 8px 12px;
    border: 1px solid #0000001a;
    text-align: left;
    vertical-align: top;
    line-height: 1.5em;
  }

  th {
    background-color: #0000000d;
  }

  iframe {
    display: block;
    width: 100%;
    border: 0;
  }
`;

export default Markdown;
